import {currency} from '@github-ui/formatters'
import {Banner} from '@primer/react'

const PAY_TO_CONTINUE_URL = '/github-copilot/pay-to-continue'
const ADDITIONAL_USAGE_LIMIT_URL = 'https://github.com/orgs/community/discussions/197089'

const dateFormatter = new Intl.DateTimeFormat('en-US', {month: 'long', day: 'numeric'})

function formatResetDate(iso: string): string {
  const [yearStr, monthStr, dayStr] = iso.split('-')
  const year = Number(yearStr)
  const month = Number(monthStr)
  const day = Number(dayStr)
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return iso
  return dateFormatter.format(new Date(year, month - 1, day))
}

interface CommonProps {
  className?: string
}

interface NotEligibleProps extends CommonProps {
  variant: 'not_eligible'
  resetDate: string
}

interface WithHeadroomProps extends CommonProps {
  variant: 'with_headroom'
  currentPlanName: string
  upgradeTargetName: string
  upgradePriceUsd: number
  creditOffsetUsd: number
  payAmountUsd: number
  resetDate: string
  upgradeUrl: string
}

interface CutUsageProps extends CommonProps {
  variant: 'cut_usage'
  currentPlanName: string
  upgradeTargetName: string
  upgradePriceUsd: number
  payAmountUsd: number
  remainingOverageAfterUpgradeUsd: number
  resetDate: string
  upgradeUrl: string
}

export type CopilotTrustTierLimitHitBannerProps = NotEligibleProps | WithHeadroomProps | CutUsageProps

function AdditionalUsageLimitLink() {
  return (
    <a href={ADDITIONAL_USAGE_LIMIT_URL} className="Link--inTextBlock">
      additional usage limit
    </a>
  )
}

function eligibleActions({upgradeUrl}: {upgradeUrl: string}) {
  return {
    primaryAction: (
      <Banner.PrimaryAction as="a" href={upgradeUrl}>
        Upgrade plan
      </Banner.PrimaryAction>
    ),
    secondaryAction: (
      <Banner.SecondaryAction as="a" href={PAY_TO_CONTINUE_URL}>
        Pay to continue
      </Banner.SecondaryAction>
    ),
  }
}

export default function CopilotTrustTierLimitHitBanner(props: CopilotTrustTierLimitHitBannerProps) {
  if (props.variant === 'not_eligible') {
    return (
      <Banner
        variant="critical"
        title="Additional usage limit reached"
        hideTitle
        className={props.className}
        data-testid="copilot-trust-tier-limit-hit-banner"
        description={`You've reached your additional usage limit for your plan. Pay for your additional usage to continue. Otherwise, wait until your credits reset on ${formatResetDate(props.resetDate)}.`}
        primaryAction={
          <Banner.PrimaryAction as="a" href={PAY_TO_CONTINUE_URL}>
            Pay to continue
          </Banner.PrimaryAction>
        }
      />
    )
  }

  const {primaryAction, secondaryAction} = eligibleActions({upgradeUrl: props.upgradeUrl})
  const description =
    props.variant === 'with_headroom' ? (
      <>
        You&apos;ve reached your <AdditionalUsageLimitLink />. Upgrade to {props.upgradeTargetName} for{' '}
        {currency(props.upgradePriceUsd)} to get an additional {currency(props.creditOffsetUsd)} in credits, or pay{' '}
        {currency(props.payAmountUsd)} to continue on {props.currentPlanName}. Credits reset{' '}
        {formatResetDate(props.resetDate)}.
      </>
    ) : (
      <>
        You&apos;ve reached your <AdditionalUsageLimitLink />. Upgrade to {props.upgradeTargetName} for{' '}
        {currency(props.upgradePriceUsd)} and cut additional usage from {currency(props.payAmountUsd)} to{' '}
        {currency(props.remainingOverageAfterUpgradeUsd)}, or pay {currency(props.payAmountUsd)} to continue on{' '}
        {props.currentPlanName}. Credits reset {formatResetDate(props.resetDate)}.
      </>
    )

  return (
    <Banner
      variant="critical"
      title="Additional usage limit reached"
      hideTitle
      className={props.className}
      data-testid="copilot-trust-tier-limit-hit-banner"
      description={description}
      primaryAction={primaryAction}
      secondaryAction={secondaryAction}
    />
  )
}
